/* ---- étapes 1 et 3 : forme, taille, motif, densité, inclinaison ---- */
function boutons(id,liste,cls,html){$(id).innerHTML=liste.map(function(o){return '<button type="button" class="'+cls+'" data-v="'+o.id+'">'+html(o)+'</button>'}).join('')}
